def transform(grid):
    n, m = len(grid), len(grid[0])
    # Reflect the source tile at the edges of a 3x3 tiling, producing a seamless mirrored pattern.
    def index(k, size):
        return size - 1 - k if k < size else (k - size if k < 2 * size else 3 * size - 1 - k)
    return [[grid[index(r, n)][index(c, m)] for c in range(3 * m)] for r in range(3 * n)]

if __name__ == '__main__':
    g = [[8,8,6],[6,3,6],[6,8,8]]
    print(transform(g))
